#include <stdio.h>
#include <stdlib.h>

int size = 0;
long heap[100];

void insert(long value) {
    heap[size] = value;
    size++;
    long current = size - 1;
    while (current > 0) {
        long parent = (current - 1) / 2;
        if (heap[parent] <= heap[current]) break;
        long temp = heap[parent];
        heap[parent] = heap[current];
        heap[current] = temp;
        current = parent;
    }
    printf("INS %ld\n", value);
}

long find_min() {
    return heap[0];
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("NOOP\n");
        return 0;
    }
    for (int i = 1; i < argc; i++) {
        long value = strtol(argv[i], NULL, 10);
        insert(value);
    }
    printf("MIN %ld\n", find_min());
    return 0;
}
